/**
 * RoomJoin asks to join a room (01 §8.4). A malformed roomId gets room_not_found, like 03's REST 404.
 */
export interface RoomJoin {
  roomId: string;
}
/**
 * RoomJoinResult is the ok payload of room.join. A room.state for the room follows immediately.
 */
export interface RoomJoinResult {
  room: RoomInfo;
}
/**
 * RoomInfo identifies a room.
 */
export interface RoomInfo {
  id: string;
  name: string;
}
/**
 * RoomState is a full snapshot of one room (01 §8.5), coalesced to at most one per 200 ms per room. Every connection
 * in the room gets byte-identical snapshots.
 */
export interface RoomState {
  roomId: string;
  rev: number /* uint64 */; // +1 per change in this server process; clients reset on every welcome
  participants: ParticipantInfo[]; // sorted by joinedAt, then userId
  shares: ShareInfo[]; // sorted by startedAt, then id
}
/**
 * ParticipantInfo merges all connections of one user in one room.
 */
export interface ParticipantInfo {
  userId: string;
  name: string;
  status: ParticipantStatus;
  joinedAt: string;
  connections: ConnectionInfo[];
}
/**
 * ParticipantStatus is present while at least one connection is ready. Clients treat unknown values as present.
 */
export const ParticipantStatusPresent = "present";
export const ParticipantStatusReconnecting = "reconnecting";
export type ParticipantStatus = typeof ParticipantStatusPresent | typeof ParticipantStatusReconnecting;
/**
 * ConnectionInfo is what everyone in the room sees about a connection. OS and version are deliberately absent
 * (privacy); admins get them from the live snapshot (01 §15.2), the user's own devices from user.connections (M2).
 * OwnConnection embeds it, so it must never get a MarshalJSON method (the embedding would hide OwnConnection's own
 * fields).
 */
export interface ConnectionInfo {
  id: string;
  kind: ClientKind;
  role: Role;
  status: ConnectionStatus;
}
/**
 * ConnectionStatus is online while the connection's socket is attached. Clients treat unknown values as online.
 */
export const ConnectionStatusOnline = "online";
export const ConnectionStatusReconnecting = "reconnecting";
export type ConnectionStatus = typeof ConnectionStatusOnline | typeof ConnectionStatusReconnecting;
/**
 * ShareInfo describes one share in room.state.
 */
export interface ShareInfo {
  id: string;
  userId: string;
  connectionId: string; // the publishing connection
  kind: ShareKind;
  label?: string; // absent: viewers render t('share.label.<kind>')
  preset: Preset;
  audio: boolean; // declared at start; after live: whether an audio track arrived
  status: ShareStatus;
  layers: VideoLayer[]; // layers whose tracks arrived (paused layers included), e.g. ["high","low"]; [] while starting
  codec?: CodecKey; // H.264 profile currently published
  startedAt: string;
  replaces?: string; // re-publish after a restart/rebuild (§10.6)
  watchers: Watcher[]; // excludes the owner (§4.1); "N watching" is len(watchers)
}
/**
 * Watcher is one participant receiving a share's video at any layer or its audio (01 §4.1), from the desired
 * subscriptions, merged over the participant's connections.
 */
export interface Watcher {
  userId: string;
  video: VideoLayer;
  audio: AudioState;
}
/**
 * RoomEvent announces a discrete change for toasts and aria-live (01 §8.6). Events are never part of a snapshot and
 * are not sent on join or resume; the UI renders from room.state.
 */
export interface RoomEvent {
  kind: RoomEventKind;
  roomId: string;
  userId: string;
  name: string; // so a toast works after the person left the snapshot
  shareId?: string;
  replaces?: string; // share.started of a re-publish: clients suppress the toast
  reason?: EndReason; // share.stopped, participant.left
  at: string;
}
/**
 * RoomEventKind is the kind of a room.event. Clients ignore unknown kinds.
 */
export const RoomEventKindParticipantJoined = "participant.joined";
export const RoomEventKindParticipantLeft = "participant.left";
export const RoomEventKindShareStarted = "share.started"; // on starting → live, once per share
export const RoomEventKindShareStopped = "share.stopped";
export type RoomEventKind = typeof RoomEventKindParticipantJoined | typeof RoomEventKindParticipantLeft | typeof RoomEventKindShareStarted | typeof RoomEventKindShareStopped;
/**
 * EndReason says why a share ended or a participant left. The strings are identical in 02's sfu package. Clients
 * show unknown reasons without a specific text.
 */
export const EndReasonStopped = "stopped"; // share.stop, pc.close, or tracks removed by the owner
export const EndReasonLeft = "left"; // room.leave / room.join elsewhere / deliberate close / closed by revocation (03)
export const EndReasonDisconnected = "disconnected"; // grace expired
export const EndReasonMediaTimeout = "media_timeout"; // starting or stalled for 30 s
export const EndReasonKicked = "kicked"; // reserved: admin kick is later
export const EndReasonRoomClosed = "room_closed"; // an admin deleted the room
export const EndReasonServerShutdown = "server_shutdown"; // shares only; never seen by clients of the new process
export type EndReason = typeof EndReasonStopped | typeof EndReasonLeft | typeof EndReasonDisconnected | typeof EndReasonMediaTimeout | typeof EndReasonKicked | typeof EndReasonRoomClosed | typeof EndReasonServerShutdown;

