// source: share.go

/**
 * ShareStart starts a share (01 §8.7). The reply is its ShareParams; the client then offers the share's tracks on
 * the pub PC.
 */
export interface ShareStart {
  kind: ShareKind;
  label?: string; // user-typed only; <= 40 code points
  preset: Preset;
  audio: boolean; // an audio track will be sent
  ref: string; // client idempotency key, 1-32 chars, unique per connection
  replaces?: string; // previous shareId of the same local capture (§10.6)
}
/**
 * ShareParams tells the sharer how to encode. The server computes it from the preset, the room's codec safe set and
 * admin limits (policy and numbers: 02). Encodings is in wire order, high first (f, then q); that is not the order
 * a web client gives the browser. Web clients (05 §13.4) pass complete sendEncodings to addTransceiver in ascending
 * order (q, then f), each with rid, active, maxBitrate, maxFramerate and scaleResolutionDownBy =
 * max(1, sqrt(width*height/maxPixels)). Later changes go through RTCRtpSender.setParameters, matched by rid.
 */
export interface ShareParams {
  shareId: string;
  codec: CodecKey; // H.264 profile to put first in setCodecPreferences
  encodings: Encoding[]; // wire order, high first (f, q); not the sendEncodings order
  audioBitrate: number /* int */; // Opus target in bit/s (the pub answer's maxaveragebitrate)
}
/**
 * Encoding is one simulcast layer's encoder settings.
 */
export interface Encoding {
  rid: string; // RIDHigh or RIDLow
  layer: VideoLayer;
  active: boolean;
  maxBitrate: number /* int64 */;
  maxFramerate: number /* int */;
  maxPixels: number /* int */; // pixel budget, aspect-ratio neutral (ultrawide screens)
}
/**
 * ShareUpdate changes the label or preset of a share of the same user. The reply carries the new ShareParams.
 */
export interface ShareUpdate {
  shareId: string;
  label?: string; // "" clears the label
  preset?: Preset;
}
/**
 * ShareStop ends a share. It is idempotent: an unknown or already ended share replies ok.
 */
export interface ShareStop {
  shareId: string;
}
/**
 * ShareKind is what is being shared. Clients treat unknown values as screen.
 */
export const ShareKindScreen = "screen"; // getDisplayMedia displaySurface "monitor"
export const ShareKindWindow = "window"; // "window"
export const ShareKindTab = "tab"; // "browser"
export type ShareKind = typeof ShareKindScreen | typeof ShareKindWindow | typeof ShareKindTab;
/**
 * Preset is the sharer's quality preset (numbers: 02). Clients treat unknown values as auto.
 */
export const PresetAuto = "auto";
export const PresetGame = "game";
export const PresetMovie = "movie";
export const PresetText = "text";
export type Preset = typeof PresetAuto | typeof PresetGame | typeof PresetMovie | typeof PresetText;
/**
 * ShareStatus is a share's state (01 §4.4). Clients treat unknown values as live.
 */
export const ShareStatusStarting = "starting";
export const ShareStatusLive = "live";
export const ShareStatusStalled = "stalled";
export type ShareStatus = typeof ShareStatusStarting | typeof ShareStatusLive | typeof ShareStatusStalled;

