/**
 * ClientStats is the client's stats report, sent every 10 s while it has a PC (01 §8.11). No IP addresses: the
 * candidate type only.
 */
export interface ClientStats {
  intervalMs: number /* int */;
  pcs: PCStats[];
  inbound?: InboundStats[];
  outbound?: OutboundStats[];
}
/**
 * PCStats describes one of the client's PCs.
 */
export interface PCStats {
  pc: PCKind;
  gen: number /* uint32 */;
  state: string; // RTCPeerConnectionState
  rttMs?: number /* int */;
  outgoingBitrate?: number /* int64 */; // availableOutgoingBitrate
  candidateType?: string; // local side of the selected pair: host|srflx|prflx|relay
  transport?: string; // udp|tcp
}
/**
 * InboundStats describes one received track.
 */
export interface InboundStats {
  shareId: string;
  kind: TrackKind;
  bitrate: number /* int64 */;
  packetsLost: number /* int64 */; // may be negative (RTCP cumulative loss with duplicates)
  jitterBufferMs?: number /* int */;
  fps?: number /* float64 */;
  width?: number /* int */;
  height?: number /* int */;
  freezeCount?: number /* int */;
  decoder?: string;
  hwDecoder?: boolean;
  codec?: CodecKey;
  /**
   * Cumulative counters since the track started (getStats values); the hub turns deltas into the
   * isshoni_client_* metrics of §18 for the M1 exit test (06 §12.3).
   */
  framesDecoded?: number /* int64 */;
  framesDropped?: number /* int64 */;
  freezeDurationMs?: number /* int64 */; // totalFreezesDuration
  concealedSamples?: number /* int64 */; // audio
  totalSamples?: number /* int64 */; // audio: totalSamplesReceived
}
/**
 * OutboundStats describes one sent track or simulcast layer.
 */
export interface OutboundStats {
  shareId: string;
  kind: TrackKind;
  rid?: string;
  bitrate: number /* int64 */;
  fps?: number /* float64 */;
  width?: number /* int */;
  height?: number /* int */;
  encoder?: string;
  hwEncoder?: boolean;
  qualityLimitation?: string; // none|cpu|bandwidth|other
}
/**
 * StatsWatch turns the server's stats stream for this connection on or off ("Stats for nerds").
 */
export interface StatsWatch {
  on: boolean;
}
/**
 * ServerStats is sent every 2 s while the connection watches stats; values come from MediaPeer.Stats() (02).
 */
export interface ServerStats {
  downlinkEstimate?: number /* int64 */; // bit/s for this connection's sub PC
  subs: ServerSubStats[];
  layers: ServerLayerStats[]; // this connection's own published layers
}
/**
 * ServerSubStats describes one forwarded track of this connection's subscriptions.
 */
export interface ServerSubStats {
  shareId: string;
  kind: TrackKind;
  layer?: VideoLayer; // video only
  bitrate: number /* int64 */;
  lossPct: number /* float64 */;
  dropped: number /* int64 */; // packets dropped by the DownTrack queue
}
/**
 * ServerLayerStats describes one received layer of this connection's own shares.
 */
export interface ServerLayerStats {
  shareId: string;
  kind: TrackKind;
  rid?: string;
  bitrate: number /* int64 */;
  lossPct: number /* float64 */;
}

