/**
 * VideoLayer is a simulcast layer, or off. Clients treat unknown values in statuses and watchers as high.
 */
export const VideoLayerHigh = "high"; // rid "f": full (source, <=1080p60 by default)
export const VideoLayerLow = "low"; // rid "q": preview (360p15)
export const VideoLayerOff = "off";
export type VideoLayer = typeof VideoLayerHigh | typeof VideoLayerLow | typeof VideoLayerOff;
/**
 * AudioState says whether a subscription forwards a share's audio.
 */
export const AudioStateOn = "on";
export const AudioStateOff = "off";
export type AudioState = typeof AudioStateOn | typeof AudioStateOff;
export const RIDHigh = "f";
export const RIDLow = "q";
/**
 * RIDs used in simulcast for each layer. Fixed for all senders (browser and native).
 */
export type RID = typeof RIDHigh | typeof RIDLow;
/**
 * SubscribeUpdate is desired state per share, merged into the connection's existing wants (01 §8.9). All changes of
 * one user action go in one update, so the server applies them atomically (audio follows focus).
 */
export interface SubscribeUpdate {
  subs: SubscriptionWant[]; // 1..64 items, unique shareIds
}
/**
 * SubscriptionWant is the desired video layer and audio of one share. {off, off} pauses a subscription but keeps its
 * transceivers.
 */
export interface SubscriptionWant {
  shareId: string;
  video: VideoLayer;
  audio: AudioState;
}
/**
 * SubscribeResult is the ok payload of subscribe.update.
 */
export interface SubscribeResult {
  ignored: string[]; // shareIds that don't exist (any more) in the connection's room
}
/**
 * SubscribeStatus reports forwarding that differs from the request, or changes back.
 */
export interface SubscribeStatus {
  subs: SubscriptionStatus[]; // only the subscriptions whose status changed
}
/**
 * SubscriptionStatus is what the server forwards for one subscription now.
 */
export interface SubscriptionStatus {
  shareId: string;
  video: VideoLayer; // being forwarded now
  audio: AudioState;
  requestedVideo: VideoLayer;
  reason?: StatusReason; // absent: video == requestedVideo
}
/**
 * StatusReason says why forwarding differs from the request. 02's finer reasons are mapped to these four (§15.4).
 * Clients show unknown reasons without a specific text.
 */
export const StatusReasonBandwidth = "bandwidth"; // server downgraded (REMB/loss estimate, 02)
export const StatusReasonUnavailable = "unavailable"; // publisher doesn't send that layer (now)
export const StatusReasonCodec = "codec"; // this client can't decode the share's codec (§11.7)
export const StatusReasonWaiting = "waiting"; // sub PC not connected yet, or waiting for a keyframe
export type StatusReason = typeof StatusReasonBandwidth | typeof StatusReasonUnavailable | typeof StatusReasonCodec | typeof StatusReasonWaiting;

