export const MaxMessageBytes = 64 << 10; // every message before welcome, and every non-SDP message after
export const MaxSDPBytes = 256 << 10; // pc.offer and pc.answer after welcome (welcome.limits.maxSdpBytes)
export const MaxStatsBytes = 16 << 10; // a client stats message
export const MaxIDLen = 32; // envelope id and re, share.start ref
export const MaxOpaqueIDLen = 64; // user, room, share and connection ids: [A-Za-z0-9_-]{1,64}
export const MaxLabelRunes = 40; // share label, in Unicode code points after trimming
export const MaxSubs = 64; // subscribe.update items
export const MaxPubTracks = 8; // tracks of a pub offer (m-sections carrying a share)
export const MaxConnSubscriptions = 256; // subscriptions per connection (02 §12, sfu.too_many_subscriptions)
export const MaxSubTracks = 2 * MaxConnSubscriptions; // tracks of a sub offer: video and audio of every subscription
export const MaxCandidateBytes = 512; // pc.ice candidate string
export const MaxFeatures = 32; // hello.features
export const MaxCodecs = 32; // caps.decode, caps.encode
export const MaxAgentKindLen = 32; // agent.send kind: [a-z.]{1,32}
export const MaxAgentPayloadBytes = 16 << 10; // agent.send payload
